class TestJestConfiguration:
    """Validate Jest configuration properly maps asset files to the mock."""

    def test_jest_config_exists(self):
        """Verify jest.config.js exists."""
        assert JEST_CONFIG.exists(), f"Jest config not found at {JEST_CONFIG}"

    def test_jest_config_valid_json(self):
        """Validate jest.config.js is parseable."""
        content = JEST_CONFIG.read_text(encoding="utf-8")
        # Strip comments and trailing commas for JSON parsing
        import re
        json_content = re.sub(r'//.*', '', content)
        json_content = re.sub(r'/\*.*?\*/', '', json_content, flags=re.DOTALL)
        json_content = re.sub(r',\s*}', '}', json_content)
        json_content = re.sub(r',\s*]', ']', json_content)
        
        try:
            config = json.loads(json_content)
        except json.JSONDecodeError as e:
            pytest.fail(f"Jest config is not valid JSON: {e}")
        
        assert isinstance(config, dict), "Jest config must be a JSON object"

    def test_jest_config_has_module_name_mapper(self):
        """Verify moduleNameMapper is configured for asset mocking."""
        content = JEST_CONFIG.read_text(encoding="utf-8")
        assert "moduleNameMapper" in content, "Jest config missing moduleNameMapper"

