class TestConcurrency:
    """Validate mock behavior under concurrent access."""

    def test_concurrent_imports(self):
        """Verify the mock handles concurrent imports safely."""
        node_path = shutil.which("node")
        if not node_path:
            pytest.skip("Node.js not available for concurrency test")
        
        with tempfile.NamedTemporaryFile(mode="w", suffix=".js", delete=False) as f:
            f.write(f"""
                const {{
                    Worker,
                    isMainThread,
                    workerData
                }} = require('worker_threads');
                
                if (isMainThread) {{
                    const workers = [];
                    for (let i = 0; i < 10; i++) {{
                        workers.push(new Promise((resolve, reject) => {{
                            const worker = new Worker(__filename);
                            worker.on('message', resolve);
                            worker.on('error', reject);
                        }}));
                    }}
                    Promise.all(workers).then(results => {{
                        const allValid = results.every(r => r === '{EXPECTED_EXPORT}');
                        if (!allValid) {{
                            console.error('Concurrent import mismatch');
                            process.exit(1);
                        }}
                        console.log('Concurrency check passed');
                    }}).catch(err => {{
                        console.error('Concurrency error:', err);
                        process.exit(1);
                    }});
                }} else {{
                    const mock = require('{str(MOCK_FILE).replace(chr(92), "/")}');
                    parentPort.postMessage(mock);
                }}
            """)
            temp_script = f.name
        
        try:
            result = subprocess.run(
                ["node", temp_script],
                capture_output=True,
                text=True,
                timeout=10
            )
            assert result.returncode == 0, f"Concurrency check failed: {result.stderr}"
            assert "Concurrency check passed" in result.stdout
        finally:
            os.unlink(temp_script)


